{
  "unit": 48,
  "font": "sans",
  "caption": "Fig. 1.1",
  "points": {
    "O": {"graph": [0, 0], "dot": false},
    "X": {"graph": [1.0, 10], "label": "X", "labelDir": "ne", "dot": true},
    "Y": {"graph": [1.2, -6], "label": "Y", "labelDir": "se", "dot": true},
    "Z": {"graph": [1.8, 0], "label": "Z", "labelDir": "n", "dot": true}
  },
  "elements": [
    {
      "type": "axes",
      "x": {
        "min": 0,
        "max": 2.8,
        "step": 0.5,
        "minor": 5,
        "label": "time / s",
        "numbers": true
      },
      "y": {
        "min": -7,
        "max": 11,
        "step": 5,
        "minor": 5,
        "label": "velocity / m/s",
        "numbers": true
      },
      "grid": "major",
      "mode": "cross",
      "sx": 2.5,
      "sy": 0.5
    },
    {
      "type": "polyline",
      "points": [
        [0, 0],
        [1.0, 10]
      ],
      "style": "solid",
      "weight": "thick"
    },
    {
      "type": "polyline",
      "points": [
        [1.0, 10],
        [1.2, -6]
      ],
      "style": "dashed",
      "weight": "thick"
    },
    {
      "type": "polyline",
      "points": [
        [1.2, -6],
        [1.8, 0]
      ],
      "style": "solid",
      "weight": "thick"
    }
  ]
}
